        cooler_cost_usd = float(cooler_cost_by_type[program['cooler_type']])
        payment_per_dispatch_per_site_usd = float(payment_by_program_code[program['program_code']])

        drug_10 = annual_drug_cost(program, active_sites, DAYS_PER_DISPATCH_10_DAY, DISPATCHES_PER_YEAR_10_DAY)
        drug_20 = annual_drug_cost(program, active_sites, DAYS_PER_DISPATCH_20_DAY, DISPATCHES_PER_YEAR_20_DAY)
        cooler_10 = annual_cooler_cost(cooler_cost_usd, DISPATCHES_PER_YEAR_10_DAY)
        cooler_20 = annual_cooler_cost(cooler_cost_usd, DISPATCHES_PER_YEAR_20_DAY)
        revenue_10 = annual_revenue(payment_per_dispatch_per_site_usd, active_sites, DISPATCHES_PER_YEAR_10_DAY)
        revenue_20 = annual_revenue(payment_per_dispatch_per_site_usd, active_sites, DISPATCHES_PER_YEAR_20_DAY)
        margin_10 = money(revenue_10 - drug_10 - cooler_10)
        margin_20 = money(revenue_20 - drug_20 - cooler_20)
        margin_difference = money(margin_20 - margin_10)

        programs.append({
            'program_code': program['program_code'],
            'program_name': program['program_name'],
            'active_sites': active_sites,
            'acquisition_cost_per_1000_units_usd': float(program['acquisition_cost_per_1000_units_usd']),
            'units_per_day': float(program['units_per_day']),
            'cooler_type': program['cooler_type'],
            'cooler_cost_usd': money(cooler_cost_usd),
            'payment_per_dispatch_per_site_usd': money(payment_per_dispatch_per_site_usd),
            'annual_drug_cost_10_day_usd': drug_10,
            'annual_drug_cost_20_day_usd': drug_20,
            'annual_cooler_cost_10_day_usd': cooler_10,
            'annual_cooler_cost_20_day_usd': cooler_20,
            'annual_revenue_10_day_usd': revenue_10,
            'annual_revenue_20_day_usd': revenue_20,
            'annual_margin_10_day_usd': margin_10,
            'annual_margin_20_day_usd': margin_20,
            'annual_margin_difference_20_minus_10_usd': margin_difference,
        })

    total_margin_10 = money(sum(program['annual_margin_10_day_usd'] for program in programs))
    total_margin_20 = money(sum(program['annual_margin_20_day_usd'] for program in programs))
    total_difference = money(sum(program['annual_margin_difference_20_minus_10_usd'] for program in programs))
    absolute_difference = money(abs(total_difference))
    decision = 'move_to_20_day' if absolute_difference < SWITCH_THRESHOLD_USD else 'keep_10_day'

    output = {
        'assumptions': {
            'dispatches_per_year_10_day': DISPATCHES_PER_YEAR_10_DAY,
            'dispatches_per_year_20_day': DISPATCHES_PER_YEAR_20_DAY,
            'days_per_dispatch_10_day': DAYS_PER_DISPATCH_10_DAY,
            'days_per_dispatch_20_day': DAYS_PER_DISPATCH_20_DAY,
            'switch_threshold_usd': SWITCH_THRESHOLD_USD,
            'site_override_rule': 'highest approved version_no per program_code, else default_active_sites',
        },
        'programs': programs,
        'totals': {
            'total_annual_margin_10_day_usd': total_margin_10,
            'total_annual_margin_20_day_usd': total_margin_20,
            'total_annual_margin_difference_20_minus_10_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
        },
    }

    with (ROOT / 'oncocooler_analysis.json').open('w') as f:
        json.dump(output, f, indent=2)

    summary_lines = [
        '# OncoCooler Dispatch Cadence Summary',
        f'Total 10-day margin (USD): {total_margin_10:.2f}',
        f'Total 20-day margin (USD): {total_margin_20:.2f}',
        f'Absolute difference (USD): {absolute_difference:.2f}',
        f'Decision: {decision}',
    ]
    (ROOT / 'oncocooler_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
